    .btn-comp  { background: transparent; border: 1px dashed #c9d6cf; color: #6b7b78; font-size: .82em; }
    .btn-comp:hover { border-color: #bbb; border-style: solid; color: #212529; }
    .btn-out-print {
      background: transparent;
      border: 1px dashed #c9d6cf;
      color: #6b7b78;
      font-size: .82em;
    }
    .btn-out-print:hover { border-color: #aaa; border-style: solid; color: #212529; }
    @media print { .btn-out-print { display: none !important; } }

    /* =========================================
       RESPONSIVO
       ========================================= */
    @media (max-width: 768px) {
      .cabecalho-site { padding: 1rem 0 .6rem; }
      .cabecalho-site h1 { font-size: 1.5rem; }
      .card-mapa { min-height: auto; }
      .lateral { max-width: 100%; overflow-x: auto; }
    }

    /* =========================================
       PRINT
       ========================================= */
    @media print {
      .navbar-custom, .cabecalho-site, .btn-coord, .btn-comp, .btn-out-print, #map { display: none !important; }
      .site-footer { background: #fff; color: #000; border-top: 1px solid #ccc; }
      .lateral .det-card { display: block !important; }
    }
  </style>
</head>
