<script>
(function () {
  "use strict";

  /* =========================================================
     1) Dados dos pontos turísticos (latitude, longitude)
     ========================================================= */
  var PONTOS = [
    {
      id: 'vero',
      nome: 'Mercado Ver-o-Peso',
      lat: -1.4473, lng: -48.4786,
      corPin: '#B35A0C',
      bairro: 'Orla do Rio Guamá — Bairro Nazaré',
