      resumo: 'Considerado o maior mercado popular ao ar livre da América Latina, reúne mais de mil barracas com farinhas (incluindo a famosa farinha do Bragança), castanhas, ervas medicinais, artesanato e uma grande variedade de comidas típicas servidas na hora.',
      destaque: 'Logo cedo, o sereno espelha-se no rio Guamá enquanto o aroma de tucumã e farinha toma conta do ar.'
    },
    {
      id: 'teatro',
      nome: 'Teatro da Paz',
      lat: -1.4717, lng: -48.4763,
      corPin: '#1A5276',
      bairro: 'Av. Presidente Vargas — Centro',
      tag: 'Arquitetura · Música · História',
      resumo: 'Inaugurado em 1897, é um dos teatros mais belos e bem preservados do Brasil. Sua fachada eclética e a cúpula revestida em mármore italiano dão a ele o apelido de "Palácio das Artes", já palco de óperas e da tradicional Semana Santa.',
      destaque: 'Ao entardecer, a cúpula branca reflete-se nos canais vizinhos em tons delicados de lilás e dourado.'
    },
    {
      id: 'bosque',
      nome: 'Bosque Rodrigues Alves',
      lat: -1.4858, lng: -48.5047,
      corPin: '#1E8449',
      bairro: 'Água Preta / Umarizal',
      tag: 'Natureza · Trilhas · Convivência',
      resumo: 'O antigo parque de exposições foi convertido em refúgio verde, com trilhas arborizadas, lago, quiosques e áreas de descanso. É a melhor escolha para fugir do calor e respirar ar puro em meio à vegetação amazônica.',
      destaque: 'Durante a semana, o silêncio das trilhas é interrompido apenas pelo canto dos pássaros e pelo riacho que atravessa o parque.'
    },
    {
      id: 'batista',
      nome: 'Praça Batista Campos',
      lat: -1.4701, lng: -48.4916,
      corPin: '#B9770E',
      bairro: 'Centro Histórico — próximo à Catedral Basílica',
      tag: 'História · Caminhada · Retratos',
      resumo: 'Pequena praça no miolo colonial da cidade, cercada por casarões antigos, ruas de pedra e o comércio tradicional. É fácil acessá-la a pé a partir de praticamente todos os bairros de Belém.',
      destaque: 'Monte um ensaio fotográfico no contraste entre os prédios centenários e o céu da Amazônia.'
    }
  ];

  /* =========================================================
     2) Utilitários
     ========================================================= */
  function primeiraMaiuscula(nome) {
    var s = String(nome || '').trim();
    return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
  }
  function escapeHtml(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] || c;
    });
  }

  /* =========================================================
     3) Ícone dos pinos (SVG gerado dinamicamente + base64)
     ========================================================= */
  var TPL_ICON =
    '<svg xmlns="http://www.w3.org/2000/svg" width="46" height="46" viewBox="0 0 46 46">' +
      '<circle cx="23" cy="23" r="21" fill="#FFFFFF" stroke="{{COR}}" stroke-width="1.6"/>' +
      '<polygon points="23,29 42,44 23,37 4,44"/>' +
    '</svg>';
  function pinoBase64(cor) {
    return 'data:image/svg+xml;base64,' + btoa(TPL_ICON.replace('{{COR}}', cor));
  }

  /* =========================================================
     4) Etiquetas textuais sobre o mapa
     ========================================================= */
  var ETIQUETAS = [
    { txt: '★ VER-O-PESO',    cor: '#9e5a12', dx: -500, dy: -160 },
    { txt: '★ TEATRO DA PAZ', cor: '#4f8bd1', dx:  150, dy: -200 },
    { txt: '★ BOSQUE R. ALVES', cor: '#3a8a40', dx: -560, dy: 40  },
    { txt: '★ PÇA. BATISTA',  cor: '#a98419', dx:  340, dy: 110 }
  ];

  /* =========================================================
     5) Mapa + marcadores + popups
     ========================================================= */
  var MAPA = L.map('map', {
    attribution: '',                        // crédito do OpenStreetMap aparece no rodapé
    zoomControl: true,
    scrollWheelZoom: true,
    dragging: true,
    keyboard: false
  }).setView([-1.4685, -48.4975], 13.5);

  L.control.zoom.position = L.bottomRight;

  /* Popups pré-montados (evitam duplicação de aberturas) */
  var POPUPS = {};
  var INDICES = {};                       // id → posição no array PONTOS

  PONTOS.forEach(function (pt, idx) {
    INDICES[pt.id] = idx;
    POPUPS[pt.id] = L.popup({
      className: 'meu-pupo ' + pt.id
    }).setContent(function () { return CONTEUDO(pt); }).addTo(MAPA);
  });

  function abrirPopup(id) {
    var p = POPUPS[id];
    if (!p || p.isOpen()) return;         // já está aberto
    p.close();
    p.openOn(MAPA);
    adicionarDestaque(id);
  }
  function fecharPopup(id) {
    var p = POPUPS[id];
    if (!p || !p.isOpen()) return;
    p.close();
    removerDestaque(id);
  }

  /* ---- Crição dos marcadores ---- */
  var MARCADORES_LAYERS = {};

  PONTOS.forEach(function (pt, idx) {
    INDICES[pt.id] = idx;

    var camada = L.marker([pt.lat, pt.lng], {
      icon: L.divIcon({
        className: 'marcador-pino pino-' + pt.id,
        iconSize: [46, 46],
        iconAnchor: [23, 23],
        popupAnchor: [0, -26],               // popup acima do pino
        backgroundImage: new Image(),
        imageSrc: pinoBase64(pt.corPin),
        imagePath: '',
        maxWidth: 46,
        maxHeight: 46,
        backgroundColor: '#FFFFFF',
        boxShadow: '0 0 7px rgba(0, 0, 0, .3)'
      })
    })
      .addTo(MAPA)
      .on('click', function () {
        var id = pt.id;
        fecharPopup(id);
        abrirPopup(id);
        MAPA.panTo(this.getLatLng(), { animate: true, duration: 1 });
        var el = document.querySelector('.pino-' + id);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      })
      .on('popupopen', function () { adicionarDestaque(pt.id); })
      .on('closePopup', function () { removerDestaque(pt.id); });

    MARCADORES_LAYERS[pt.id] = camada;
  });

  /* =========================================================
     6) Destaque do marcador selecionado
     ========================================================= */
  function limparDestaque() {
    document.querySelectorAll('.marcador-pino').forEach(function (el) {
      el.classList.remove('pino-selecionada');
    });
  }
  function adicionarDestaque(id) {
    limparDestaque();
    var el = document.querySelector('.pino-' + id);
    if (el) el.classList.add('pino-selecionada');
  }
  function removerDestaque(id) {
    var el = document.querySelector('.pino-' + id);
    if (el) el.classList.remove('pino-selecionada');
  }

  /* =========================================================
     7) Lenda + abertura animada dos cartões
     ========================================================= */
  var UL = document.getElementById('ulLegenda');
  var CONTROLES_DETALHE = []; // wrappers de transição

  /* --- Gera a lista de legendas clicáveis --- */
  PONTOS.forEach(function (pt) {
    var li = document.createElement('li');
    li.className = 'd-flex align-items-center gap-4';
    li.dataset.ponto = pt.id;
    li.tabindex = 0;
    li.innerHTML =
      '<span class="dot" style="background:' + pt.corPin + ';width:24px;height:24px;border-radius:50%;font-size:.6em;font-weight:700;flex-shrink:0;margin-right:9px;">' +
        primeiraMaiuscula(pt.nome) + '</span>' +
      pt.nome;
    var onClick = function () {
      var aberta = li.classList.toggle('item-destacada');
      abrirDetalhe(pt.id, aberta);
      destacarLegenda(pt.id, aberta);
    };
    li.addEventListener('click', onClick);
    li.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick.call(li);
      }
    });
    UL.appendChild(li);
  });

  /* --- Monta os cartões de detalhe (dentro de wrappers animados) --- */
  PONTOS.forEach(function (pt) {
    var controle = document.createElement('div');
    controle.className = 'det-controle';
    CONTROLES_DETALHE.push(controle);

    var partes = pt.tag.split('·');
    var parteA = partes[0].trim();
    var resto = partes.slice(1).join(' · ');

    var card = document.createElement('div');
    card.className = 'det-card ' + pt.id;
    card.innerHTML =
      '<div class="d-flex align-items-center gap-3 mb-2">' +
        '<span class="dot" style="width:20px;height:20px;border-radius:50%;background:' + pt.corPin + ';font-size:.55em;color:#fff;flex-shrink:0;">●</span>' +
        '<h5 class="card-title mb-0">' + primeiraMaiuscula(pt.nome) + '</h5>' +
      '</div>' +
      '<span class="info-tag">' + pt.bairro + '</span>' +
      '<hr class="my-3">' +
      '<p class="text-muted small mb-2">' + pt.resumo + '</p>' +
      '<span class="badge-mini">' + parteA + '</span>' +
      '<span class="badge-mini">' + resto + '</span>';
    controle.appendChild(card);
    CONTROLES_DETALHE.push(controle);
  });

  /* Abertura/animação dos detalhes */
  function abrirDetalhe(id, abrir) {
    var ctrl = document.getElementById('det-' + id);
    if (!abrir) {
      ctrl.style.maxHeight = '0px';
      ctrl.style.transform = 'translateY(8px)';
      ctrl.style.opacity = '0';
      return;
    }
    var altura = ctrl.scrollHeight;
    ctrl.style.display = '';
    ctrl.style.maxHeight = altura + 'px';
    setTimeout(function () {
      ctrl.style.transform = 'translateY(0)';
      ctrl.style.opacity = '1';
    }, 70);
    destacar(id);
  }

  /* Sincroniza legendas e destaque do mapa */
  function destacar(id) {
    var lis = document.querySelectorAll('.lista-legenda li');
    lis.forEach(function (l) {
      l.classList.toggle('item-destacada', l.dataset.ponto === id);
    });
    adicionarDestaque(id);
  }
  function retirarDestaque(id) {
    destacar(id);
    var el = document.querySelector('.pino-' + id);
    if (el) el.classList.remove('pino-selecionada');
  }

  /* =========================================================
     8) Interações pequenas
     ========================================================= */
  var anoSpan = document.getElementById('ano');
  if (anoSpan) anoSpan.textContent = new Date().getFullYear();

  /* Botão de coordenadas (copia tudo para a área de transferência) */
  var btnCoord = document.querySelector('.btn-coord');
  if (btnCoord) {
    btnCoord.addEventListener('click', function () {
      var txt = PONTOS.map(function (pt) {
        return pt.lat.toFixed(6) + ', ' + pt.lng.toFixed(6);
      }).join('; ');
      novaToast('Coordenadas GPS:\n\n' + txt, 'success');
    });
  }

  /* Janela/modal de compartilhamento simplificado */
  var btnComp = document.querySelector('.btn-comp');
  if (btnComp) {
    btnComp.target = '_blank';
    btnComp.rel = 'noopener noreferrer';
  }

  /* Toast customizado */
  var TOASTBOX = document.getElementById('toastBox');
  function novaToast(msg, tipo) {
    tipo = ('bg-' + (tipo || 'primary')).toLowerCase();
    var t = document.createElement('div');
    t.className = 'toast position-fixed bottom-0 end-0 m-0 shadow-lg border-0 opacity-0';
    t.setAttribute('role', 'alert');
    t.setAttribute('aria-live', 'polite');
    t.innerHTML =
      '<div class="toast-body text-white fw-semibold">' +
        msg.replace(/\n/g, '<br>') + '</div>' +
      '<button type="button" class="btn-close btn-close-white d-none d-sm-inline" data-bs-dismiss="static" aria-label="Fechar toast"></button>';
    TOASTBOX.appendChild(t);

    setTimeout(function () { t.classList.add('show'); }, 90);

    setTimeout(function () {
      t.style.transition = 'opacity .3s ease, transform .3s ease';
      var fechar = t.querySelector('.btn-close');
      if (!fechar) return;
      fechar.setAttribute('aria-label', 'Fechar aviso');
      fechar.addEventListener('click', function () { t.remove(); });
      fechar.addEventListener('touchstart', function () {
        if (!t._temp) t._temp = setTimeout(function () { t.remove(); }, 2600);
      }, { passive: true });
      t._temp = setTimeout(function () { t.remove(); }, 2900);
    }, 310);
  }

  /* =========================================================
     9) Feito
     ========================================================= */
})();
</script>
</body>
</html>
